50	const PROCESSING_FEE = 5;
51	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
52	
53	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
54	  sword: 100,
55	  amulet: 60,
56	  staff: 80,
57	  potion: 40,
58	  rune: 25,
59	  moonstone: 25,
60	};
61	
62	/** Percentages are applied as integer arithmetic so that the final
63	 *  rounding is not corrupted by float artifacts (100 * 1.1 === 110.000…1). */
64	const addPercent = (amount: number, percent: number): number =>
65	  amount + (amount * percent) / 100;
66	
67	/** Rounds up — premiums round in the MHPCO's favour. */
68	const roundPremium = (amount: number): number => Math.ceil(amount);
69	
70	const COMPONENT_BLOCK_SIZE = 3;
71	const COMPONENT_BLOCK_BASE_PREMIUM = 60;
72	
73	const itemBasePremium = (item: Item): number =>
74	  BASE_PREMIUM_BY_TYPE[item.type];
75	
76	const policyBasePremium = (items: Item[]): number => {
77	  if (
78	    items.length === COMPONENT_BLOCK_SIZE &&
79	    items.every((item) => item.type === "rune")
80	  ) {
81	    return COMPONENT_BLOCK_BASE_PREMIUM;
82	  }
83	  return items.reduce((total, item) => total + itemBasePremium(item), 0);
84	};
85	
86	const quote = (items: Item[]): QuoteResult => {
87	  const basePremium = policyBasePremium(items);
88	  const modifiedPremium = addPercent(
89	    basePremium,
90	    FIRST_INSURANCE_SURCHARGE_PERCENT,
91	  );
92	  // The processing fee is added last, after all percentage modifiers.
93	  const premium = modifiedPremium + PROCESSING_FEE;
94	  return { premium: roundPremium(premium) };
95	};
96	
97	const runStep = (step: Step): StepResult => {
98	  if (step.op === "quote") return quote(step.items);
99	  throw new Error(`Unsupported step: ${step.op}`);
100	};
101	
102	export const runScenario = (scenario: Scenario): ScenarioResult => {
103	  const results = scenario.steps.map(runStep);
104	  return { results };
105	};
