/** A block is exactly three alike components, priced as a unit rather than
 *  per item. Only the all-rune case is driven by a test so far. */
const isComponentBlock = (items: Item[]): boolean =>
  items.length === COMPONENT_BLOCK_SIZE &&
  items.every((item) => item.type === "rune");

const sumItemBasePremiums = (items: Item[]): number =>
  items.reduce((total, item) => total + itemBasePremium(item), 0);

const policyBasePremium = (items: Item[]): number =>
  isComponentBlock(items)
    ? COMPONENT_BLOCK_BASE_PREMIUM
    : sumItemBasePremiums(items);
